  void _onToolExecutionStart(
    String toolCallId,
    String toolName,
    Map<String, dynamic> args,
  ) {
    for (final key in const ['path', 'file', 'filePath', 'target']) {
      final value = args[key];
      if (value is String && value.isNotEmpty) _touchedPaths.add(value);
