final class StreamLivenessHeartbeat {
  StreamLivenessHeartbeat({
    required void Function(int elapsedSeconds) onRemind,
    int Function()? livenessSeconds,
    int Function()? tickSeconds,
    DateTime Function()? clock,
  }) : _onRemind = onRemind,
