    if (_useTui && tuiChromeEnabled) {
      io.writeln(
        tuiToolCard(
          ToolCardSegments(title: toolName, description: detail),
          TuiCardPhase.running,
          _rowWidth,
        ).join('\n'),
      );
      return;
    }
    io.writeln(
      tuiToolRow(
        layoutToolRow(
          ToolRowSegments(glyph: '•', label: toolName, detail: detail),
          _rowWidth - 2,
        ),
        ToolRowState.running,
      ),
