blocks.text:
/// one assistant response plus any tool calls/results it triggers. Partial
/// snapshots follow the partial-first invariant: every [MessageUpdateEvent]
/// carries the live partial [AssistantMessage].
sealed class AgentEvent {
  const AgentEvent();
}

/// The loop started processing a prompt or continuation.
final class AgentStartEvent extends AgentEvent {
  const AgentStartEvent();
}

/// The loop finished. Always the last event; carries every message produced
/// by this run (prompts included for [agentLoop], excluded for
/// [agentLoopContinue]).
final class AgentEndEvent extends AgentEvent {
  const AgentEndEvent(this.messages);

  /// Messages produced by this run, in order.
  final List<Message> messages;
}

/// The agent is fully idle: the run AND every queued follow-up have drained
/// and all awaited listeners for the run's events (including `agent_end`)
/// have settled (pi's `agent_settled`).
///
/// Emitted only by the stateful `Agent` (in agent.dart), after the last
/// [AgentEndEvent] of a run and before [Agent.waitForIdle] resolves — the
/// low-level loop never emits it, so [AgentEventStream] still completes on
/// [AgentEndEvent].
final class AgentSettledEvent extends AgentEvent {
  const AgentSettledEvent();
}

/// A new turn (assistant response + tool calls) started.
final class TurnStartEvent extends AgentEvent {
  const TurnStartEvent();
}

/// A turn finished: the assistant message completed and its tool calls (if
/// any) produced [toolResults].
final class TurnEndEvent extends AgentEvent {
  const TurnEndEvent({required this.message, required this.toolResults});

  /// The completed assistant message of this turn.
  final AssistantMessage message;

  /// Tool results produced this turn, in assistant source order.
  final List<ToolResultMessage> toolResults;
}

/// A message entered the transcript: a prompt, a (partial) assistant
/// message, or a tool result.
final class MessageStartEvent extends AgentEvent {
  const MessageStartEvent(this.message);

  /// The message. For assistant messages this is the first partial snapshot.
  final Message message;
}

/// The streamed assistant message advanced. Only emitted for assistant
/// messages; [message] is the live partial snapshot carried by
/// [assistantMessageEvent].
final class MessageUpdateEvent extends AgentEvent {
  const MessageUpdateEvent({
    required this.message,
    required this.assistantMessageEvent,
  });

  /// The live partial assistant message.
  final AssistantMessage message;

  /// The underlying provider event that produced this update.
  final AssistantMessageEvent assistantMessageEvent;
}

/// A message is complete: the final assistant message, a prompt, or a tool
/// result.
final class MessageEndEvent extends AgentEvent {
  const MessageEndEvent(this.message);

  /// The final message.
  final Message message;
}

/// Execution of a tool call started.
final class ToolExecutionStartEvent extends AgentEvent {
  const ToolExecutionStartEvent({
    required this.toolCallId,
    required this.toolName,
    required this.args,
    required this.timestamp,
  });

  /// The [ToolCall.id] being executed.
  final String toolCallId;

  /// The tool's name.
  final String toolName;

  /// The parsed tool call arguments.
  final Map<String, dynamic> args;

  /// Wall-clock time the execution started.
  final DateTime timestamp;
}

/// The outbound request summary captured before a provider call.
///
/// Emitted right before [StreamFunction] runs; [detail] describes the exact
/// payload about to be sent (message count/sizes, tool names). The
/// trajectory builder attaches it to the assistant step the request
/// produces, and hosts persist it (a hidden `model_request_summary`
/// record) so replayed sessions keep the same Request tab data.
final class ModelRequestEvent extends AgentEvent {
  const ModelRequestEvent({
    required this.detail,
    this.promptBlob,
    this.manifestBlob,
    this.rawWireDump,
  });

  /// Cheap summary of the outbound request payload.
  final TrajectoryRequestDetail detail;

  /// The full system prompt sent with this request (issue #385 F1), for
  /// hosts to persist once per content hash. Null when the request had no
  /// system prompt.
  final TrajectoryPromptBlob? promptBlob;

  /// The complete tool manifest (names, descriptions, schemas — F2), for
  /// hosts to persist once per content hash. Null when no tools were sent.
  final TrajectoryToolManifestBlob? manifestBlob;

  /// The RAW serialized outbound request JSON (F5), only when
  /// [AgentLoopConfig.wireDump] is on. Hosts MUST redact (secrets live in
  /// plaintext inside) and cap before persisting.
  final String? rawWireDump;
}

/// Emitted when the outbound request context needed tool-pairing surgery
/// (issue #85): orphaned tool results dropped, missing results synthesized,
/// or duplicate ids renamed. Repairs are never silent — [report] carries
/// the counts and affected ids, and [providerError] is set when the pass
/// ran in response to a provider pairing error (the self-healing retry).
final class ToolPairingRepairEvent extends AgentEvent {
  const ToolPairingRepairEvent({required this.report, this.providerError});

  /// What the repair changed (empty report = detection only).
  final ToolPairingRepairReport report;

  /// Raw provider error that triggered this pass, when it ran on the
  /// retry path; null for the pre-request repair.
  final String? providerError;
}

/// The FinalizeGate task ledger parsed from the run's final assistant
/// message (gh-1412). Emitted once per run, right before [AgentEndEvent],
/// when [AgentLoopConfig.finalizeGate] is on and the answer carries a
/// `task-ledger` fenced block. Hosts persist it as a hidden
/// `task_ledger` session record (the TaskLedger — post-mortems see WHAT
/// was self-checked, the bench summary reports near-miss proximity); the
/// trajectory snapshot builder folds persisted records back on replay.
final class TaskLedgerEvent extends AgentEvent {
